+			return messages;
+		}
+		catch (JsonProcessingException e) {
+			throw new IllegalStateException("Failed to deserialize messages: " + e.getMessage(), e);
+		}
+	}
+
+	/**
+	 * Converts JSON metadata node to Map.
+	 * @param metadataNode the JSON metadata node
