+					+ "' from S3 bucket '" + this.config.getBucketName() + "': " + e.getMessage(), e);
+		}
+		catch (Exception e) {
+			throw new IllegalStateException(
+					"Failed to retrieve conversation '" + normalizedConversationId + "': " + e.getMessage(), e);
+		}
+	}
